using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class WalkFullLayout {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var floor=JObject.Parse(File.ReadAllText(repo+"/Docs/도면/Decision/원형공동/facility_layout.json"))["floors"].Single(f=>(string)f["id"]=="B5");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();
 try{foreach(var t in floor["tunnels"]){Vector3 a=new Vector3((float)t["p"][0],-82,-(float)t["p"][1]),b=new Vector3((float)t["q"][0],-82,-(float)t["q"][1]);var dir=(b-a).normalized;a-=dir*1.4f;b+=dir*1.4f;foreach(bool reverse in new[]{false,true}){var p=reverse?b:a;var q=reverse?a:b;cc.enabled=false;player.transform.position=p+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();int steps=0;float remaining=0;for(int i=0;i<2000;i++){var delta=q-player.transform.position;delta.y=0;remaining=delta.magnitude;if(remaining<.06f)break;cc.Move(delta.normalized*Mathf.Min(.10f,remaining)+Vector3.down*.08f);steps++;}var feet=player.transform.position+Vector3.up*(cc.center.y-cc.height*.5f);float heightError=Mathf.Abs(feet.y+82);results.Add(new{id=(string)t["id"],reverse,steps,remaining,heightError,passed=remaining<.10f&&heightError<.13f});}}}
 finally{cc.enabled=false;player.transform.position=old;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}
 File.WriteAllText(repo+"/Docs/검수/2026-11-06_B5_FullLayout/controller_walk.json",JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
}
